PRINT N'--- db/procs/fn_group_for_role.sql';
EXEC (N'/* =====================================================================
   app.fn_group_for_role        APP-1 helper (used by app.usp_route_resolve and
                                app.vw_route_check, so the rule lives in ONE place)
   Single statement per file; CREATE OR ALTER, safe to run again.

   Input : a role name or an alias from app.role_alias (routes may name an alias,
           for example "Operations-IOC - NMD"), and a profit centre.
   Output: exactly one row: role_name (alias resolved) and group_key (NULL when no
           group holds that role for that profit centre).

   Group choice (03 APP-1 step 5): the group is the GROUP assignment of that role whose
   scope contains the profit centre; an explicit profit-centre list beats ALL_ORCM; on a
   tie the lowest assignment_id wins. An inactive role or assignment never matches.
   ===================================================================== */
CREATE OR ALTER FUNCTION app.fn_group_for_role
(
    @role_or_alias      nvarchar(64),
    @profit_center_name nvarchar(40)
)
RETURNS TABLE
AS
RETURN
(
    SELECT x.role_name, g.group_key
    FROM (SELECT COALESCE((SELECT al.role_name FROM app.role_alias AS al WHERE al.alias_name = @role_or_alias), @role_or_alias) AS role_name) AS x
    OUTER APPLY
    (
        SELECT TOP (1) a.principal_key AS group_key
        FROM app.principal_role_assignment AS a
        JOIN app.role AS ro ON ro.role_name = a.role_name AND ro.is_active = 1
        WHERE a.is_active = 1
          AND a.principal_type = N''GROUP''
          AND a.role_name = x.role_name
          AND (a.scope_type = N''ALL_ORCM''
               OR EXISTS (SELECT 1 FROM app.principal_role_assignment_scope AS s
                          WHERE s.assignment_id = a.assignment_id AND s.profit_center_name = @profit_center_name))
        ORDER BY CASE WHEN a.scope_type = N''ALL_ORCM'' THEN 1 ELSE 0 END, a.assignment_id
    ) AS g
);
');

PRINT N'--- db/procs/usp_identity_resolve.sql';
EXEC (N'/* =====================================================================
   app.usp_identity_resolve     APP-1; contract: FINAL PLAN/01 section 6.8
   Single statement per file; CREATE OR ALTER, safe to run again.

   Turns the user id found in the caller''s token (the text after /users/ at the end
   of `sub`) into the person''s e-mail. The function calls this first, then passes the
   e-mail on as @actor_email to the one business procedure.

   Returns ONE row (user_email, display_name) for an active identity, and NO row for
   an unknown, inactive or empty id: the function then answers NOT_REGISTERED.
   Case and outer spaces in the id are ignored. Reads one table, changes nothing.
   ===================================================================== */
CREATE OR ALTER PROCEDURE app.usp_identity_resolve
    @external_id nvarchar(64)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT TOP (1)
        CAST(i.user_email   AS nvarchar(256)) AS user_email,
        CAST(i.display_name AS nvarchar(100)) AS display_name
    FROM app.principal_identity AS i
    WHERE i.external_id = LOWER(LTRIM(RTRIM(@external_id)))
      AND i.is_active = 1
    ORDER BY i.identity_id;
END
');

PRINT N'--- db/procs/usp_principal_profile.sql';
EXEC (N'/* =====================================================================
   app.usp_principal_profile    APP-1; FINAL PLAN/01 section 3 ("What a user may do")
   Single statement per file; CREATE OR ALTER, safe to run again.

   Input : the person''s e-mail (as returned by app.usp_identity_resolve).
   Output: ONE result set, one row per (assignment x profit centre):
     user_email, display_name, is_registered   the person (repeated on every row)
     role_name, granted_via, group_key         the role and where it comes from:
                                               USER (assigned to the person), GROUP (through
                                               a group they belong to), IMPLICIT (see below)
     scope_type, profit_center_name            ALL_ORCM (profit_center_name NULL) or one
                                               row per profit centre of the list
     the ten role flags (can_view ... can_manage_admin)

   The caller combines rows: a flag is on when it is on in ANY row; an approval stage
   is allowed only for the profit centres of the rows that carry that flag.

   IMPLICIT row: every registered person also holds the role GeneralViewer ("All OXY
   Users" [REF-46:L0204]), so a registered person with no assignment can still view and
   submit [INFERRED: reading of that description]. No rows at all = unregistered and
   without assignments.

   Reads only; changes nothing. Never raises for an unknown e-mail.
   ===================================================================== */
CREATE OR ALTER PROCEDURE app.usp_principal_profile
    @email nvarchar(256)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @e nvarchar(256) = LOWER(LTRIM(RTRIM(@email)));
    DECLARE @name nvarchar(100) =
        (SELECT TOP (1) i.display_name FROM app.principal_identity AS i
         WHERE i.user_email = @e AND i.is_active = 1 ORDER BY i.identity_id);
    DECLARE @registered bit =
        CASE WHEN EXISTS (SELECT 1 FROM app.principal_identity AS i WHERE i.user_email = @e AND i.is_active = 1) THEN 1 ELSE 0 END;

    DECLARE @mine TABLE
    (
        assignment_id int           NULL,
        role_name     nvarchar(64)  NOT NULL,
        scope_type    nvarchar(20)  NOT NULL,
        granted_via   nvarchar(10)  NOT NULL,
        group_key     nvarchar(64)  NULL
    );

    -- assigned to the person directly
    INSERT INTO @mine (assignment_id, role_name, scope_type, granted_via, group_key)
    SELECT a.assignment_id, a.role_name, a.scope_type, N''USER'', NULL
    FROM app.principal_role_assignment AS a
    WHERE a.is_active = 1 AND a.principal_type = N''USER'' AND a.principal_key = @e;

    -- assigned to a group the person belongs to
    INSERT INTO @mine (assignment_id, role_name, scope_type, granted_via, group_key)
    SELECT a.assignment_id, a.role_name, a.scope_type, N''GROUP'', m.group_key
    FROM app.group_membership AS m
    JOIN app.principal_role_assignment AS a
         ON a.principal_type = N''GROUP'' AND a.principal_key = m.group_key AND a.is_active = 1
    WHERE m.is_active = 1 AND m.user_email = @e;

    -- everyone registered is a general viewer
    INSERT INTO @mine (assignment_id, role_name, scope_type, granted_via, group_key)
    SELECT NULL, N''GeneralViewer'', N''ALL_ORCM'', N''IMPLICIT'', NULL
    WHERE @registered = 1
      AND EXISTS (SELECT 1 FROM app.role AS r WHERE r.role_name = N''GeneralViewer'' AND r.is_active = 1);

    SELECT
        CAST(@e          AS nvarchar(256)) AS user_email,
        CAST(@name       AS nvarchar(100)) AS display_name,
        @registered                        AS is_registered,
        CAST(mm.role_name   AS nvarchar(64)) AS role_name,
        CAST(mm.granted_via AS nvarchar(10)) AS granted_via,
        CAST(mm.group_key   AS nvarchar(64)) AS group_key,
        CAST(mm.scope_type  AS nvarchar(20)) AS scope_type,
        CAST(s.profit_center_name AS nvarchar(40)) AS profit_center_name,
        r.can_view,
        r.can_submit_requests,
        r.can_request_edit_business_rules,
        r.can_publish_business_rules,
        r.can_request_edit_evidence_guidance,
        r.can_publish_evidence_guidance,
        r.can_responsible_approve,
        r.can_accountable_approve,
        r.can_manage_admin
    FROM @mine AS mm
    JOIN app.role AS r ON r.role_name = mm.role_name AND r.is_active = 1
    LEFT JOIN app.principal_role_assignment_scope AS s
         ON s.assignment_id = mm.assignment_id AND mm.scope_type = N''PROFIT_CENTER_LIST''
    ORDER BY mm.role_name, mm.granted_via, mm.group_key, s.profit_center_name;
END
');

PRINT N'--- db/procs/usp_route_resolve.sql';
EXEC (N'/* =====================================================================
   app.usp_route_resolve        APP-1; FINAL PLAN/03 APP-1 step 5, 09 section 3.7
   Single statement per file; CREATE OR ALTER, safe to run again.

   Who approves a change? Input: entity type, action, profit centre, and optionally
   the field and the class of the heater / FLOC. Output: ONE row
     route_id, route_used, responsible_role, responsible_group,
     accountable_role, accountable_group

   Which route: among the active routes that match the entity, the action, the field
   (the route''s field is ''*'' or equals @field_code) and the class (the route covers any
   class, or lists @class_code), the most specific wins:
     FIELD+CLASS (rank 3) > FIELD (rank 2) > CLASS (rank 1) > WILDCARD (rank 0);
   equal rank: the lowest route_id. [INFERRED from REF-46:L0210-L0223 and the meeting
   statement quoted in POC-APP-03.]

   Which group: the route names ROLES (an alias such as "Operations-IOC - NMD" is
   resolved through app.role_alias); the group is chosen by app.fn_group_for_role
   (explicit profit-centre list beats ALL_ORCM). No route or no group: ''UNROUTED'',
   which admins see on S-13.

   Reads only; changes nothing. Never raises on unknown input: it answers NONE / UNROUTED.
   ===================================================================== */
CREATE OR ALTER PROCEDURE app.usp_route_resolve
    @entity_type        nvarchar(10),
    @request_action     nvarchar(10),
    @profit_center_name nvarchar(40),
    @field_code         nvarchar(64) = NULL,
    @class_code         nvarchar(30) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @route_id int, @route_used nvarchar(12), @resp_raw nvarchar(64), @acc_raw nvarchar(64);

    SELECT TOP (1)
        @route_id   = r.route_id,
        @resp_raw   = r.responsible_role,
        @acc_raw    = r.accountable_role,
        @route_used = CASE WHEN r.field_or_characteristic <> N''*'' AND r.class_scope = N''LIST'' THEN N''FIELD+CLASS''
                           WHEN r.field_or_characteristic <> N''*'' THEN N''FIELD''
                           WHEN r.class_scope = N''LIST'' THEN N''CLASS''
                           ELSE N''WILDCARD'' END
    FROM app.approval_route AS r
    WHERE r.is_active = 1
      AND r.entity_type = @entity_type
      AND r.request_action = @request_action
      AND (r.field_or_characteristic = N''*'' OR r.field_or_characteristic = @field_code)
      AND (r.class_scope = N''ANY''
           OR EXISTS (SELECT 1 FROM app.approval_route_class AS c WHERE c.route_id = r.route_id AND c.class_code = @class_code))
    ORDER BY (CASE WHEN r.field_or_characteristic <> N''*'' THEN 2 ELSE 0 END
              + CASE WHEN r.class_scope = N''LIST'' THEN 1 ELSE 0 END) DESC,
             r.route_id;

    DECLARE @resp_role nvarchar(64), @resp_group nvarchar(64), @acc_role nvarchar(64), @acc_group nvarchar(64);

    IF @route_id IS NOT NULL
    BEGIN
        SELECT @resp_role = g.role_name, @resp_group = g.group_key
        FROM app.fn_group_for_role(@resp_raw, @profit_center_name) AS g;

        SELECT @acc_role = g.role_name, @acc_group = g.group_key
        FROM app.fn_group_for_role(@acc_raw, @profit_center_name) AS g;
    END

    SELECT
        @route_id                                   AS route_id,
        ISNULL(@route_used, N''NONE'')                AS route_used,
        @resp_role                                  AS responsible_role,
        ISNULL(@resp_group, N''UNROUTED'')            AS responsible_group,
        @acc_role                                   AS accountable_role,
        ISNULL(@acc_group, N''UNROUTED'')             AS accountable_group;
END
');

PRINT N'--- db/views/vw_group_member_count.sql';
EXEC (N'/* =====================================================================
   app.vw_group_member_count    APP-1; FINAL PLAN/09 section 9; screen S-13 (Admin)
   Single statement per file; CREATE OR ALTER, safe to run again.

   One row per defined group (app.security_group): its roles and how many active
   people belong to it. Key: group_key. Exposed through the connector: explicit
   types, no nvarchar(max). E-mail addresses are never part of this view.
   ===================================================================== */
CREATE OR ALTER VIEW app.vw_group_member_count
AS
SELECT
    CAST(g.group_key     AS nvarchar(64))  AS group_key,
    CAST(g.display_name  AS nvarchar(100)) AS display_name,
    CAST(ISNULL(ro.roles, N'''') AS nvarchar(400)) AS roles,
    CAST((SELECT COUNT(*) FROM app.group_membership AS m WHERE m.group_key = g.group_key AND m.is_active = 1) AS int) AS active_member_count
FROM app.security_group AS g
OUTER APPLY
(
    SELECT STRING_AGG(x.role_name, N'', '') WITHIN GROUP (ORDER BY x.role_name) AS roles
    FROM (SELECT DISTINCT a.role_name
          FROM app.principal_role_assignment AS a
          WHERE a.principal_type = N''GROUP'' AND a.principal_key = g.group_key AND a.is_active = 1) AS x
) AS ro
WHERE g.is_active = 1;
');

PRINT N'--- db/views/vw_route_check.sql';
EXEC (N'/* =====================================================================
   app.vw_route_check           APP-1; FINAL PLAN/09 section 9; screen S-13 (Admin)
   Single statement per file; CREATE OR ALTER, safe to run again.

   One row per approval route x profit centre: the groups it resolves to and how many
   active members each has. This is the POC-DE-27 acceptance check: a stage with fewer
   than two members stops work when one person is away [DBF-DOC:L0039]. The client''s
   own file has one member in most groups, so most rows show has_two_members = 0.

   Key: route_check_key (route_id + ''|'' + profit centre). Exposed through the connector:
   every column has an explicit type and there is no nvarchar(max).
   Profit centres are the ones named in the scope lists of the assignments (the ten
   ORCM values of 01 section 3). Group choice is app.fn_group_for_role, the same code
   app.usp_route_resolve uses.
   ===================================================================== */
CREATE OR ALTER VIEW app.vw_route_check
AS
SELECT
    CAST(CONVERT(nvarchar(20), r.route_id) + N''|'' + pc.profit_center_name AS nvarchar(80)) AS route_check_key,
    CAST(r.route_id                  AS int)           AS route_id,
    CAST(r.entity_type               AS nvarchar(10))  AS entity_type,
    CAST(r.request_action            AS nvarchar(10))  AS request_action,
    CAST(r.field_or_characteristic   AS nvarchar(64))  AS field_or_characteristic,
    CAST(r.class_scope               AS nvarchar(10))  AS class_scope,
    CAST(pc.profit_center_name       AS nvarchar(40))  AS profit_center_name,
    CAST(rg.role_name                AS nvarchar(64))  AS responsible_role,
    CAST(ISNULL(rg.group_key, N''UNROUTED'') AS nvarchar(64)) AS responsible_group,
    CAST(rc.n                        AS int)           AS responsible_member_count,
    CAST(ag.role_name                AS nvarchar(64))  AS accountable_role,
    CAST(ISNULL(ag.group_key, N''UNROUTED'') AS nvarchar(64)) AS accountable_group,
    CAST(ac.n                        AS int)           AS accountable_member_count,
    CAST(CASE WHEN rg.group_key IS NOT NULL AND ag.group_key IS NOT NULL THEN 1 ELSE 0 END AS bit) AS is_resolved,
    CAST(CASE WHEN rc.n >= 2 AND ac.n >= 2 THEN 1 ELSE 0 END AS bit) AS has_two_members
FROM app.approval_route AS r
CROSS JOIN (SELECT DISTINCT s.profit_center_name FROM app.principal_role_assignment_scope AS s) AS pc
CROSS APPLY app.fn_group_for_role(r.responsible_role, pc.profit_center_name) AS rg
CROSS APPLY app.fn_group_for_role(r.accountable_role, pc.profit_center_name) AS ag
CROSS APPLY (SELECT COUNT(*) AS n FROM app.group_membership AS m WHERE m.group_key = rg.group_key AND m.is_active = 1) AS rc
CROSS APPLY (SELECT COUNT(*) AS n FROM app.group_membership AS m WHERE m.group_key = ag.group_key AND m.is_active = 1) AS ac
WHERE r.is_active = 1;
');

PRINT N'=== end of app1_3_procs_views ===';
